import base64

b64 = ""

html = base64.b64decode(b64).decode("utf-8")
start = html.find("<svg")
end = html.find("</svg>") + 6
svg = html[start:end]

with open("/workspace/report/IMDb_Tables_Row_Count_chart.svg", "w", encoding="utf-8") as f:
    f.write(svg)
print(f"SVG saved, length: {len(svg)} chars")
